<?php
function exportInventoryButtons(array $types): void { ?><div class="export-actions"><?php foreach($types as $type=>$label):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="inventory_export"><input type="hidden" name="type" value="<?=e($type)?>"><button class="btn secondary">↓ <?=e($label)?></button></form><?php endforeach?></div><?php }
function linkedOrderSelect(string $label,string $name,array $orders,bool $required=false): void { ?><label><?=e($label)?><select name="<?=e($name)?>" <?=$required?'required':''?>><option value=""><?=$required?'Choisir une commande':'Sans commande'?></option><?php foreach($orders as $o):?><option value="<?=(int)$o['id']?>"><?=e(ref((int)$o['id']).' · '.$o['title'])?></option><?php endforeach?></select></label><?php }
function inventorySummary(array $pairs): void { ?><div class="finance-summary"><?php foreach($pairs as $label=>$value):?><div><span><?=e($label)?></span><strong><?=e($value)?></strong></div><?php endforeach?></div><?php }
if($page==='stock'):
    $q=mb_substr(trim((string)($_GET['q']??'')),0,120);$archived=($_GET['archived']??'0')==='1'?1:0;$filter=($_GET['alerts']??'0')==='1';
    $where='i.archived=?';$args=[$archived];if($q!==''){$where.=' AND (i.code LIKE ? OR i.name LIKE ? OR i.supplier LIKE ?)';$args=[...$args,'%'.$q.'%','%'.$q.'%','%'.$q.'%'];}
    $base="SELECT i.*,(SELECT COALESCE(SUM(m.quantity*m.direction),0) FROM stock_movements m WHERE m.item_id=i.id) physical_quantity,(SELECT COALESCE(SUM(r.quantity),0) FROM stock_reservations r WHERE r.item_id=i.id AND r.state='Active') reserved_quantity FROM stock_items i WHERE ".$where;
    if($filter)$base='SELECT x.* FROM ('.$base.') x WHERE physical_quantity-reserved_quantity<=min_quantity';
    $count=(int)scalar('SELECT COUNT(*) FROM ('.$base.') list',$args);$current=max(1,min(max(1,(int)ceil($count/20)),(int)($_GET['p']??1)));$items=all($base.' ORDER BY name,id LIMIT 20 OFFSET '.(($current-1)*20),$args);
    heading('MATIÈRES & CONSOMMABLES','Le bon stock, au bon moment.','Les quantités physiques proviennent des mouvements. Le disponible déduit les réservations actives.','Ajouter un article',url('stock_form'));
    ?><section class="panel"><form method="get" class="filter-bar"><input type="hidden" name="page" value="stock"><label class="search-field"><span class="sr-only">Rechercher un article</span><input name="q" value="<?=e($q)?>" placeholder="Référence, matière, fournisseur…"></label><select name="archived" aria-label="État"><option value="0">Articles actifs</option><option value="1" <?=$archived?'selected':''?>>Archivés</option></select><select name="alerts" aria-label="Alertes"><option value="0">Tous les niveaux</option><option value="1" <?=$filter?'selected':''?>>Sous le seuil</option></select><button class="btn secondary">Filtrer</button></form><?php if(!$items):emptyState('Aucun article à afficher.','Ajoutez une matière puis enregistrez une première entrée.','Ajouter un article',url('stock_form'));else:?><div class="table-scroll"><table><thead><tr><th>ARTICLE</th><th>FOURNISSEUR</th><th>ENTRÉE / EXPIRATION</th><th class="numeric">VENTE HT / UNITÉ</th><th class="numeric">POIDS UNITAIRE</th><th class="numeric">PHYSIQUE</th><th class="numeric">RÉSERVÉ</th><th class="numeric">DISPONIBLE</th><th>NIVEAU</th><th>ÉTAT</th></tr></thead><tbody><?php foreach($items as $i):$onhand=qty($i['physical_quantity']);$reserved=qty($i['reserved_quantity']);$available=$onhand-$reserved;$alert=$available<=qty($i['min_quantity']);?><tr><td><a class="record-title" href="<?=e(url('stock_form',['id'=>$i['id']]))?>"><?=e($i['name'])?></a><small class="subline"><?=e($i['code'].' · '.$i['family'])?></small></td><td><?=e($i['supplier'])?:'—'?><small class="subline"><?=e($i['location'])?></small></td><td>Entrée : <?=e(stockDate($i['entry_date']))?><small class="subline">Expiration : <?=e(stockDate($i['expiry_date']))?></small><?php if($i['expiry_date']):?><small class="subline <?=$i['expiry_date']<=date('Y-m-d')?'overdue':''?>"><?=e(stockExpiryLabel($i['expiry_date']))?></small><?php endif?></td><td class="numeric">Gros : <?=$i['wholesale_price']!==null?e(money($i['wholesale_price'])):'—'?><small class="subline">Détail : <?=$i['retail_price']!==null?e(money($i['retail_price'])):'—'?></small></td><td class="numeric"><?=$i['unit_weight_kg']!==null?e($i['unit_weight_kg'].' kg'):'—'?></td><td class="numeric"><?=e(quantityText($onhand).' '.$i['unit'])?></td><td class="numeric"><?=e(quantityText($reserved))?></td><td class="numeric amount"><?=e(quantityText($available).' '.$i['unit'])?></td><td><span class="tag <?=$alert?'yellow':'green'?>"><?=$alert?'À réapprovisionner':'Suffisant'?></span><small class="subline">Seuil <?=e($i['min_quantity'].' '.$i['unit'])?></small></td><td><form method="post" data-confirm="<?=e($archived?'Réactiver cet article ?':'Archiver cet article ? Le stock et les réservations doivent être à zéro.')?>"><?=csrf()?><input type="hidden" name="action" value="stock_archive"><input type="hidden" name="id" value="<?=(int)$i['id']?>"><input type="hidden" name="archived" value="<?=$archived?'0':'1'?>"><button class="text-button"><?=$archived?'Réactiver':'Archiver'?></button></form></td></tr><?php endforeach?></tbody></table></div><?php pagination($count,$current,'stock',['q'=>$q,'archived'=>$archived,'alerts'=>(int)$filter]);endif?></section><?php exportInventoryButtons(['stock'=>'Articles CSV','movements'=>'Mouvements CSV','reservations'=>'Réservations CSV']);?>
<?php elseif($page==='stock_form'):
    $id=max(0,(int)($_GET['id']??0));$item=$id?row('SELECT * FROM stock_items WHERE id=?',[$id]):[];if($id&&!$item){emptyState('Article introuvable.','Revenez au stock.','Stock',url('stock'));return;}
    $v=($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='stock_save')?($_POST+$item):$item;
    heading('MATIÈRES & CONSOMMABLES',$id?$item['code'].' · '.$item['name']:'Une nouvelle matière.','L’unité est conservée dès le premier mouvement. Les quantités se saisissent dans le journal, jamais en écrasant un solde.');
    if($id&&$item['expiry_date']&&$item['expiry_date']<=date('Y-m-d')):?><div class="notice info"><?=e(stockExpiryLabel($item['expiry_date']))?> · <?=e(stockDate($item['expiry_date']))?>. Vérifiez la matière avant utilisation.</div><?php endif;
    if($id){$balance=stockBalance($id);inventorySummary(['Physique'=>quantityText($balance['onhand']).' '.$item['unit'],'Réservé'=>quantityText($balance['reserved']).' '.$item['unit'],'Disponible'=>quantityText($balance['available']).' '.$item['unit'],'Seuil'=>rtrim(rtrim($item['min_quantity'],'0'),'.').' '.$item['unit']]);}
    ?><form method="post" class="panel editor-form"><?=csrf()?><input type="hidden" name="action" value="stock_save"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><?php inputField('Nom de la matière','name',$v['name']??'','text',true,'maxlength="190"');inputField('Référence · automatique si vide','code',$v['code']??'','text',false,'maxlength="50"');selectField('Famille','family',STOCK_FAMILIES,$v['family']??'Vinyle');selectField('Unité','unit',STOCK_UNITS,$v['unit']??'m²');inputField('Seuil d’alerte','min_quantity',$v['min_quantity']??'0.000','number',true,'min="0" max="99999999.999" step="0.001"');inputField('Coût unitaire de référence · DH','reference_cost',$v['reference_cost']??'0.00','number',true,'min="0" max="999999999.99" step="0.01"');inputField('Date d’entrée initiale','entry_date',$v['entry_date']??($id?'':date('Y-m-d')),'date',false,'max="'.e(date('Y-m-d')).'"');inputField('Date d’expiration · facultative','expiry_date',$v['expiry_date']??'','date');inputField('Prix de vente en gros · DH HT / unité','wholesale_price',$v['wholesale_price']??'','number',false,'min="0" max="999999999.99" step="0.01"');inputField('Prix de vente au détail · DH HT / unité','retail_price',$v['retail_price']??'','number',false,'min="0" max="999999999.99" step="0.01"');inputField('Poids unitaire · kg par unité de stock','unit_weight_kg',$v['unit_weight_kg']??'','number',false,'min="0.001" max="99999999.999" step="0.001"');inputField('Fournisseur','supplier',$v['supplier']??'','text',false,'maxlength="190"');inputField('Emplacement','location',$v['location']??'','text',false,'maxlength="190"');?><label class="full-width">Notes<textarea name="notes" rows="3" maxlength="5000"><?=e($v['notes']??'')?></textarea></label></div><p class="small muted">Dates, tarifs et poids décrivent cette fiche article ; pour des lots avec des dates différentes, utilisez des fiches distinctes. Le poids concerne une unité de stock. Les tarifs HT sont indicatifs et ne modifient pas les commandes existantes. Le coût de référence est indicatif ; il ne calcule pas un coût moyen pondéré ni une marge comptable.</p><div class="form-footer"><a class="btn secondary" href="<?=e(url('stock'))?>">Retour au stock</a><button class="btn primary">Enregistrer l’article</button></div></form>
    <?php if($id&&!$item['archived']):$orders=all("SELECT id,title FROM orders WHERE status NOT IN ('Livrée','Annulée') ORDER BY id DESC");?><div class="settings-grid commerce-block"><section class="panel padded"><h2>Entrée, sortie ou correction</h2><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="stock_move"><input type="hidden" name="item_id" value="<?=$id?>"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><?php selectField('Type de mouvement','kind',MOVEMENT_KINDS,'Entrée');inputField('Quantité · '.$item['unit'],'quantity','','number',true,'min="0.001" max="99999999.999" step="0.001"');linkedOrderSelect('Commande liée · facultatif','order_id',$orders);inputField('Motif / référence du bon','reason','','text',true,'maxlength="500"');?><button class="btn primary">Enregistrer le mouvement</button></form></section><section class="panel padded"><h2>Réserver pour une commande</h2><p class="muted small">Le physique reste inchangé ; le disponible diminue. Pour utiliser ce stock, consommez la réservation.</p><?php if($orders):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="stock_reserve"><input type="hidden" name="item_id" value="<?=$id?>"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><?php linkedOrderSelect('Commande','order_id',$orders,true);inputField('Quantité à réserver · '.$item['unit'],'quantity','','number',true,'min="0.001" max="99999999.999" step="0.001"');inputField('Note','note','','text',false,'maxlength="500"');?><button class="btn secondary">Réserver la quantité</button></form><?php else:?><p class="muted small">Aucune commande en cours. Créez une commande avant de réserver.</p><?php endif?></section></div><?php endif?>
    <?php if($id):$reservationCount=(int)scalar('SELECT COUNT(*) FROM stock_reservations WHERE item_id=?',[$id]);$reservationPages=max(1,(int)ceil($reservationCount/50));$reservationPage=max(1,min($reservationPages,(int)($_GET['rpage']??1)));$reservations=all('SELECT r.*,o.title FROM stock_reservations r JOIN orders o ON o.id=r.order_id WHERE item_id=? ORDER BY r.id DESC LIMIT 50 OFFSET '.(($reservationPage-1)*50),[$id]);?><section class="panel commerce-block"><div class="panel-heading"><div><h2>Réservations</h2><p>50 par page ; export CSV pour l’historique complet.</p></div></div><?php if(!$reservations):emptyState('Aucune réservation.','Les réservations de cette matière apparaîtront ici.');else:?><div class="table-scroll"><table><thead><tr><th>COMMANDE</th><th>QUANTITÉ</th><th>ÉTAT</th><th>CRÉÉE LE</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($reservations as $r):?><tr><td><a class="record-title" href="<?=e(url('order_form',['id'=>$r['order_id']]))?>"><?=e(ref((int)$r['order_id']))?></a><small class="subline"><?=e($r['title'])?></small></td><td><?=e($r['quantity'].' '.$item['unit'])?></td><td><span class="tag <?=$r['state']==='Active'?'yellow':'gray'?>"><?=e($r['state'])?></span></td><td><?=e(localDate($r['created_at']))?></td><td><div class="row-actions"><?php if($r['state']==='Active'):foreach(['Consommée'=>'Consommer','Libérée'=>'Libérer'] as $state=>$label):?><form method="post" data-confirm="<?=e($state==='Consommée'?'Consommer cette réservation et enregistrer une sortie de stock ?':'Libérer cette quantité réservée ?')?>"><?=csrf()?><input type="hidden" name="action" value="reservation_resolve"><input type="hidden" name="reservation_id" value="<?=(int)$r['id']?>"><input type="hidden" name="state" value="<?=e($state)?>"><button class="text-button"><?=e($label)?></button></form><?php endforeach;endif?></div></td></tr><?php endforeach?></tbody></table></div><?php endif?><?php if($reservationPages>1):?><div class="pagination"><span>Page <?=$reservationPage?> / <?=$reservationPages?></span><div><?php if($reservationPage>1):?><a class="btn secondary" href="<?=e(url('stock_form',['id'=>$id,'rpage'=>$reservationPage-1]))?>">← Précédent</a><?php endif?><?php if($reservationPage<$reservationPages):?><a class="btn secondary" href="<?=e(url('stock_form',['id'=>$id,'rpage'=>$reservationPage+1]))?>">Suivant →</a><?php endif?></div></div><?php endif?></section><section class="panel commerce-block"><div class="panel-heading"><div><h2>Journal de stock</h2><p>50 derniers mouvements ; corrections par nouveau mouvement, sans effacer l’historique.</p></div></div><div class="table-scroll"><table><thead><tr><th>DATE</th><th>OPÉRATION</th><th>QUANTITÉ</th><th>COMMANDE</th><th>MOTIF</th></tr></thead><tbody><?php foreach(all('SELECT * FROM stock_movements WHERE item_id=? ORDER BY id DESC LIMIT 50',[$id]) as $m):?><tr><td><?=e(localDate($m['created_at']))?></td><td><?=e($m['kind'])?></td><td><?=($m['direction']>0?'+':'−').e($m['quantity'].' '.$item['unit'])?></td><td><?= $m['order_id']?e(ref((int)$m['order_id'])):'—'?></td><td><?=e($m['reason'])?></td></tr><?php endforeach?></tbody></table></div></section><?php exportInventoryButtons(['movements'=>'Tous les mouvements CSV','reservations'=>'Toutes les réservations CSV']);endif?>
<?php elseif($page==='equipment'):
    $q=mb_substr(trim((string)($_GET['q']??'')),0,120);$archived=($_GET['archived']??'0')==='1'?1:0;$filter=(string)($_GET['state']??'');$where='archived=?';$args=[$archived];if(in_array($filter,EQUIPMENT_STATES,true)){$where.=' AND state=?';$args[]=$filter;}else $filter='';if($q!==''){$where.=' AND (name LIKE ? OR model LIKE ? OR serial_number LIKE ?)';$args=[...$args,'%'.$q.'%','%'.$q.'%','%'.$q.'%'];}
    $count=(int)scalar('SELECT COUNT(*) FROM equipment WHERE '.$where,$args);$current=max(1,min(max(1,(int)ceil($count/20)),(int)($_GET['p']??1)));$items=all('SELECT * FROM equipment WHERE '.$where.' ORDER BY name,id LIMIT 20 OFFSET '.(($current-1)*20),$args);
