    ?><section class="panel"><form method="get" class="filter-bar"><input type="hidden" name="page" value="equipment"><label class="search-field"><span class="sr-only">Recherche matériel</span><input name="q" value="<?=e($q)?>" placeholder="Machine, modèle ou numéro de série…"></label><select name="state" aria-label="État machine"><option value="">Tous les états</option><?php foreach(EQUIPMENT_STATES as $state):?><option <?=$filter===$state?'selected':''?>><?=e($state)?></option><?php endforeach?></select><select name="archived" aria-label="Archivage"><option value="0">Actifs</option><option value="1" <?=$archived?'selected':''?>>Archivés</option></select><button class="btn secondary">Filtrer</button></form><?php if(!$items):emptyState('Aucun équipement.','Ajoutez vos imprimantes, machines CNC, lasers ou autres équipements.');else:?><div class="table-scroll"><table><thead><tr><th>ÉQUIPEMENT</th><th>EMPLACEMENT</th><th>ÉTAT</th><th>PROCHAINE MAINTENANCE</th><th>ACTION</th></tr></thead><tbody><?php foreach($items as $eq):?><tr><td><a class="record-title" href="<?=e(url('equipment_form',['id'=>$eq['id']]))?>"><?=e($eq['name'])?></a><small class="subline">EQ-<?=str_pad((string)$eq['id'],5,'0',STR_PAD_LEFT)?> · <?=e($eq['model'])?></small></td><td><?=e($eq['location'])?:'—'?></td><td><span class="tag <?=$eq['state']==='Disponible'?'green':($eq['state']==='En panne'?'yellow':'gray')?>"><?=e($eq['state'])?></span></td><td><span class="<?=$eq['next_service']&&$eq['next_service']<=date('Y-m-d')?'overdue':''?>"><?=e($eq['next_service']?:'À planifier')?></span><?php if($eq['next_service']&&$eq['next_service']<=date('Y-m-d')):?><small class="subline overdue">À traiter</small><?php endif?></td><td><form method="post" data-confirm="<?=e($archived?'Réactiver cet équipement ?':'Archiver cet équipement et conserver son historique ?')?>"><?=csrf()?><input type="hidden" name="action" value="equipment_archive"><input type="hidden" name="id" value="<?=(int)$eq['id']?>"><input type="hidden" name="archived" value="<?=$archived?'0':'1'?>"><button class="text-button"><?=$archived?'Réactiver':'Archiver'?></button></form></td></tr><?php endforeach?></tbody></table></div><?php pagination($count,$current,'equipment',['q'=>$q,'state'=>$filter,'archived'=>$archived]);endif?></section><?php exportInventoryButtons(['equipment'=>'Équipements CSV','events'=>'Interventions CSV']);?>
