    <?php if($id):inventorySummary(['Interventions'=>(string)scalar('SELECT COUNT(*) FROM equipment_events WHERE equipment_id=?',[$id]),'Coût total interventions'=>money(scalar('SELECT COALESCE(SUM(cost),0) FROM equipment_events WHERE equipment_id=?',[$id])),'État actuel'=>$eq['state'],'Prochaine échéance'=>$eq['next_service']?:'À planifier']);if(!$eq['archived']):?><section class="panel padded commerce-block"><h2>Enregistrer une intervention réalisée</h2><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="equipment_event"><input type="hidden" name="equipment_id" value="<?=$id?>"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="form-grid"><?php selectField('Type','event_type',EVENT_TYPES,'Entretien');inputField('Date de l’intervention','event_date',date('Y-m-d'),'date',true,'max="'.date('Y-m-d').'"');inputField('Coût de l’intervention · DH','cost','0.00','number',true,'min="0" max="999999999.99" step="0.01"');selectField('État actuel après saisie','state_after',EQUIPMENT_STATES,$eq['state']);inputField('Nouvelle échéance · vide = aucune','next_service',$eq['next_service']??'','date');?><label class="full-width">Description<textarea name="description" required rows="3" maxlength="5000"></textarea></label></div><button class="btn primary">Enregistrer l’intervention</button></form></section><?php endif?><section class="panel commerce-block"><div class="panel-heading"><div><h2>Historique des interventions</h2><p>50 dernières ; l’export contient l’historique complet.</p></div></div><div class="table-scroll"><table><thead><tr><th>DATE / TYPE</th><th>DESCRIPTION</th><th class="numeric">COÛT</th><th>ÉTAT APRÈS</th><th>ÉCHÉANCE</th></tr></thead><tbody><?php foreach(all('SELECT * FROM equipment_events WHERE equipment_id=? ORDER BY id DESC LIMIT 50',[$id]) as $ev):?><tr><td><?=e($ev['event_date'])?><small class="subline"><?=e($ev['event_type'])?></small></td><td><?=nl2br(e($ev['description']))